아래는 위 예시를 조금 더 견고하게 만든 버전입니다.

`src/providers/provider.router.ts`

```ts
import {
  MessageProvider,
  ProviderType,
  SendMessageInput,
  SendMessageResult,
} from './provider.types';

export class ProviderRouter {
  private readonly providerMap: ReadonlyMap<ProviderType, MessageProvider>;

  constructor(providers: readonly MessageProvider[]) {
    const map = new Map<ProviderType, MessageProvider>();

    for (const provider of providers) {
      if (map.has(provider.type)) {
        throw new Error(`Duplicate provider registered: ${provider.type}`);
      }
      map.set(provider.type, provider);
    }

    this.providerMap = map;
  }

  hasProvider(type: ProviderType): boolean {
    return this.providerMap.has(type);
  }

  getProvider(type: ProviderType): MessageProvider {
    const provider = this.providerMap.get(type);
    if (!provider) {
      throw new Error(`Provider not found: ${type}`);
    }
    return provider;
  }

  async send(
    type: ProviderType,
    input: SendMessageInput,
  ): Promise<SendMessageResult> {
    const provider = this.getProvider(type);
    return provider.send(input);
  }
}
```

