# 5. Provider Router 구현

`src/providers/provider.router.ts`

```ts
import {
  MessageProvider,
  ProviderType,
  SendMessageInput,
} from './provider.types';

export class ProviderRouter {
  private readonly providerMap: Map<ProviderType, MessageProvider>;

  constructor(providers: MessageProvider[]) {
    this.providerMap = new Map();

    for (const provider of providers) {
      if (this.providerMap.has(provider.type)) {
        throw new Error(`Duplicate provider registered: ${provider.type}`);
      }
      this.providerMap.set(provider.type, provider);
    }
  }

  getProvider(type: ProviderType): MessageProvider {
    const provider = this.providerMap.get(type);

    if (!provider) {
      throw new Error(`Provider not found for type: ${type}`);
    }

    return provider;
  }

  async send(type: ProviderType, input: SendMessageInput) {
    const provider = this.getProvider(type);
    return provider.send(input);
  }
}
```

이 router는:

- provider 등록
- 중복 등록 방지
- 타입별 provider 조회
- `send()` 위임

을 담당합니다.

