## 1) 설계 개요

권장 구조:

- `AIProvider` 인터페이스
- `ProviderResult`, `ProviderError` 타입 정의
- 각 provider 구현체 (`OpenAIProvider`, `AnthropicProvider`, `GoogleProvider` 등)
- orchestration 함수 `generateWithFallback`
- timeout / retry 유틸
- provider별 실패 원인 수집

동작 방식:

1. 우선순위대로 provider 호출
2. timeout, rate limit, 일시적 네트워크 오류는 retry 가능
3. 최종 실패 시 다음 provider로 fallback
4. 모든 provider 실패 시 aggregate error 반환

---

## 2) 코드 예시

아래 코드는 바로 프로젝트에 넣어 확장 가능한 형태입니다.

```ts
// ai-orchestrator.ts

export type AIModelMessage = {
  role: "system" | "user" | "assistant";
  content: string;
};

export type GenerateTextParams = {
  messages: AIModelMessage[];
  temperature?: number;
  maxTokens?: number;
  signal?: AbortSignal;
  metadata?: Record<string, unknown>;
};

export type ProviderUsage = {
  inputTokens?: number;
  outputTokens?: number;
  totalTokens?: number;
};

export type ProviderResult = {
  provider: string;
  model: string;
  text: string;
  usage?: ProviderUsage;
  latencyMs: number;
  finishReason?: string;
};

export type ProviderErrorCode =
  | "TIMEOUT"
  | "RATE_LIMIT"
  | "AUTH"
  | "INVALID_REQUEST"
  | "NETWORK"
  | "SERVER"
  | "ABORTED"
  | "UNKNOWN";

export class ProviderError extends Error {
  public readonly provider: string;
  public readonly code: ProviderErrorCode;
  public readonly retryable: boolean;
  public readonly status?: number;
  public readonly cause?: unknown;

  constructor(params: {
    provider: string;
    message: string;
    code: ProviderErrorCode;
    retryable: boolean;
    status?: number;
    cause?: unknown;
  }) {
    super(params.message);
    this.name = "ProviderError";
    this.provider = params.provider;
    this.code = params.code;
    this.retryable = params.retryable;
    this.status = params.status;
    this.cause = params.cause;
  }
}

export interface AIProvider {
  readonly name: string;
  generateText(params: GenerateTextParams): Promise<ProviderResult>;
}

export type RetryPolicy = {
  maxAttempts: number;
  baseDelayMs: number;
  maxDelayMs: number;
  jitter?: boolean;
};

export type FallbackAttempt = {
  provider: string;
  success: boolean;
  latencyMs: number;
  error?: {
    message: string;
    code?: ProviderErrorCode;
    retryable?: boolean;
    status?: number;
  };
};

export type GenerateWithFallbackResult = {
  result: ProviderResult;
  attempts: FallbackAttempt[];
};

export type GenerateWithFallbackOptions = {
  providers: AIProvider[];
  retryPolicy?: RetryPolicy;
  perProviderTimeoutMs?: number;
  shouldRetry?: (error: unknown) => boolean;
  shouldFallback?: (error: unknown) => boolean;
  onAttemptStart?: (providerName: string, attemptNumber: number) => void;
  onAttemptFailure?: (providerName: string, error: unknown, attemptNumber: number) => void;
  onProviderFallback?: (fromProvider: string, error: unknown) => void;
  onSuccess?: (providerName: string, result: ProviderResult) => void;
};

export class AllProvidersFailedError extends Error {
  public readonly attempts: FallbackAttempt[];

  constructor(attempts: FallbackAttempt[]) {
    super("All AI providers failed");
    this.name = "AllProvidersFailedError";
    this.attempts = attempts;
  }
}

function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

function computeBackoffDelay(
  attempt: number,
  baseDelayMs: number,
  maxDelayMs: number,
  jitter = true
): number {
  const exp = Math.min(maxDelayMs, baseDelayMs * 2 ** (attempt - 1));
  if (!jitter) return exp;
  const randomized = exp * (0.5 + Math.random() * 0.5);
  return Math.floor(randomized);
}

function isAbortError(error: unknown): boolean {
  return error instanceof Error && error.name === "AbortError";
}

function normalizeUnknownError(provider: string, error: unknown): ProviderError {
  if (error instanceof ProviderError) {
    return error;
  }

  if (isAbortError(error)) {
    return new ProviderError({
      provider,
      message: "Request aborted",
      code: "ABORTED",
      retryable: false,
      cause: error,
    });
  }

  return new ProviderError({
    provider,
    message: error instanceof Error ? error.message : "Unknown provider error",
    code: "UNKNOWN",
    retryable: false,
    cause: error,
  });
}

function defaultShouldRetry(error: unknown): boolean {
  const normalized =
    error instanceof ProviderError
      ? error
      : new ProviderError({
          provider: "unknown",
          message: error instanceof Error ? error.message : "Unknown error",
          code: "UNKNOWN",
          retryable: false,
          cause: error,
        });

  return normalized.retryable;
}

function defaultShouldFallback(error: unknown): boolean {
  const normalized =
    error instanceof ProviderError
      ? error
      : new ProviderError({
          provider: "unknown",
          message: error instanceof Error ? error.message : "Unknown error",
          code: "UNKNOWN",
          retryable: false,
          cause: error,
        });

  // 일반적으로 auth / invalid request는 다음 provider로 넘겨도 의미가 있을 수 있음
  // (provider별 API 형식 차이로 인해), 하지만 정책에 따라 조정 가능
  return normalized.code !== "ABORTED";
}

async function withTimeout<T>(
  promiseFactory: (signal: AbortSignal) => Promise<T>,
  timeoutMs: number,
  externalSignal?: AbortSignal,
  providerName?: string
): Promise<T> {
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), timeoutMs);

  const abortHandler = () => controller.abort();
  externalSignal?.addEventListener("abort", abortHandler);

  try {
    return await promiseFactory(controller.signal);
  } catch (error) {
    if (controller.signal.aborted && !externalSignal?.aborted) {
      throw new ProviderError({
        provider: providerName ?? "unknown",
        message: `Provider request timed out after ${timeoutMs}ms`,
        code: "TIMEOUT",
        retryable: true,
        cause: error,
      });
    }
    throw error;
  } finally {
    clearTimeout(timeout);
    externalSignal?.removeEventListener("abort", abortHandler);
  }
}

async function executeWithRetry(
  provider: AIProvider,
  params: GenerateTextParams,
  retryPolicy: RetryPolicy,
  timeoutMs: number,
  shouldRetry: (error: unknown) => boolean,
  hooks?: {
    onAttemptStart?: (providerName: string, attemptNumber: number) => void;
    onAttemptFailure?: (providerName: string, error: unknown, attemptNumber: number) => void;
  }
): Promise<ProviderResult> {
  let lastError: unknown;

  for (let attempt = 1; attempt <= retryPolicy.maxAttempts; attempt++) {
    hooks?.onAttemptStart?.(provider.name, attempt);

    try {
      const result = await withTimeout(
        (signal) => provider.generateText({ ...params, signal }),
        timeoutMs,
        params.signal,
        provider.name
      );
      return result;
    } catch (error) {
      const normalized = normalizeUnknownError(provider.name, error);
      lastError = normalized;
      hooks?.onAttemptFailure?.(provider.name, normalized, attempt);

      const canRetry =
        attempt < retryPolicy.maxAttempts &&
        !params.signal?.aborted &&
        shouldRetry(normalized);

      if (!canRetry) {
        throw normalized;
      }

      const delay = computeBackoffDelay(
        attempt,
        retryPolicy.baseDelayMs,
        retryPolicy.maxDelayMs,
        retryPolicy.jitter ?? true
      );

      await sleep(delay);
    }
  }

  throw normalizeUnknownError(provider.name, lastError);
}

export async function generateWithFallback(
  params: GenerateTextParams,
  options: GenerateWithFallbackOptions
): Promise<GenerateWithFallbackResult> {
  const {
    providers,
    retryPolicy = {
      maxAttempts: 2,
      baseDelayMs: 300,
      maxDelayMs: 2000,
      jitter: true,
    },
    perProviderTimeoutMs = 15_000,
    shouldRetry = defaultShouldRetry,
    shouldFallback = defaultShouldFallback,
    onAttemptStart,
    onAttemptFailure,
    onProviderFallback,
    onSuccess,
  } = options;

  if (!providers.length) {
    throw new Error("At least one provider must be configured");
  }

  const attempts: FallbackAttempt[] = [];

  for (const provider of providers) {
    const startedAt = Date.now();

    try {
      const result = await executeWithRetry(
        provider,
        params,
        retryPolicy,
        perProviderTimeoutMs,
        shouldRetry,
        {
          onAttemptStart,
          onAttemptFailure,
        }
      );

      const latencyMs = Date.now() - startedAt;
      attempts.push({
        provider: provider.name,
        success: true,
        latencyMs,
      });

      onSuccess?.(provider.name, result);

      return {
        result,
        attempts,
      };
    } catch (error) {
      const normalized = normalizeUnknownError(provider.name, error);
      const latencyMs = Date.now() - startedAt;

      attempts.push({
        provider: provider.name,
        success: false,
        latencyMs,
        error: {
          message: normalized.message,
          code: normalized.code,
          retryable: normalized.retryable,
          status: normalized.status,
        },
      });

      if (!shouldFallback(normalized) || params.signal?.aborted) {
        throw new AllProvidersFailedError(attempts);
      }

      onProviderFallback?.(provider.name, normalized);
    }
  }

  throw new AllProvidersFailedError(attempts);
}
```

