function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

function computeBackoffDelay(
  attempt: number,
  baseDelayMs: number,
  maxDelayMs: number,
  jitter = true
): number {
  const exp = Math.min(maxDelayMs, baseDelayMs * 2 ** (attempt - 1));
  if (!jitter) return exp;
  const randomized = exp * (0.5 + Math.random() * 0.5);
  return Math.floor(randomized);
}

function isAbortError(error: unknown): boolean {
  return error instanceof Error && error.name === "AbortError";
}

function normalizeUnknownError(provider: string, error: unknown): ProviderError {
  if (error instanceof ProviderError) {
    return error;
  }

  if (isAbortError(error)) {
    return new ProviderError({
      provider,
      message: "Request aborted",
      code: "ABORTED",
      retryable: false,
      cause: error,
    });
  }

  return new ProviderError({
    provider,
    message: error instanceof Error ? error.message : "Unknown provider error",
    code: "UNKNOWN",
    retryable: false,
    cause: error,
  });
}

function defaultShouldRetry(error: unknown): boolean {
  const normalized =
    error instanceof ProviderError
      ? error
      : new ProviderError({
          provider: "unknown",
          message: error instanceof Error ? error.message : "Unknown error",
          code: "UNKNOWN",
          retryable: false,
          cause: error,
        });

  return normalized.retryable;
}

function defaultShouldFallback(error: unknown): boolean {
  const normalized =
    error instanceof ProviderError
      ? error
      : new ProviderError({
          provider: "unknown",
          message: error instanceof Error ? error.message : "Unknown error",
          code: "UNKNOWN",
          retryable: false,
          cause: error,
        });

  // 일반적으로 auth / invalid request는 다음 provider로 넘겨도 의미가 있을 수 있음
  // (provider별 API 형식 차이로 인해), 하지만 정책에 따라 조정 가능
  return normalized.code !== "ABORTED";
}

async function withTimeout<T>(
  promiseFactory: (signal: AbortSignal) => Promise<T>,
  timeoutMs: number,
  externalSignal?: AbortSignal,
  providerName?: string
): Promise<T> {
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), timeoutMs);

  const abortHandler = () => controller.abort();
  externalSignal?.addEventListener("abort", abortHandler);

  try {
    return await promiseFactory(controller.signal);
  } catch (error) {
    if (controller.signal.aborted && !externalSignal?.aborted) {
      throw new ProviderError({
        provider: providerName ?? "unknown",
        message: `Provider request timed out after ${timeoutMs}ms`,
        code: "TIMEOUT",
        retryable: true,
        cause: error,
      });
    }
    throw error;
  } finally {
    clearTimeout(timeout);
    externalSignal?.removeEventListener("abort", abortHandler);
  }
}

async function executeWithRetry(
  provider: AIProvider,
  params: GenerateTextParams,
  retryPolicy: RetryPolicy,
  timeoutMs: number,
  shouldRetry: (error: unknown) => boolean,
  hooks?: {
    onAttemptStart?: (providerName: string, attemptNumber: number) => void;
    onAttemptFailure?: (providerName: string, error: unknown, attemptNumber: number) => void;
  }
): Promise<ProviderResult> {
  let lastError: unknown;

  for (let attempt = 1; attempt <= retryPolicy.maxAttempts; attempt++) {
    hooks?.onAttemptStart?.(provider.name, attempt);

    try {
      const result = await withTimeout(
        (signal) => provider.generateText({ ...params, signal }),
        timeoutMs,
        params.signal,
        provider.name
      );
      return result;
    } catch (error) {
      const normalized = normalizeUnknownError(provider.name, error);
      lastError = normalized;
      hooks?.onAttemptFailure?.(provider.name, normalized, attempt);

      const canRetry =
        attempt < retryPolicy.maxAttempts &&
        !params.signal?.aborted &&
        shouldRetry(normalized);

      if (!canRetry) {
        throw normalized;
      }

      const delay = computeBackoffDelay(
        attempt,
        retryPolicy.baseDelayMs,
        retryPolicy.maxDelayMs,
        retryPolicy.jitter ?? true
      );

      await sleep(delay);
    }
  }

  throw normalizeUnknownError(provider.name, lastError);
}

export async function generateWithFallback(
  params: GenerateTextParams,
  options: GenerateWithFallbackOptions
): Promise<GenerateWithFallbackResult> {
  const {
    providers,
    retryPolicy = {
      maxAttempts: 2,
      baseDelayMs: 300,
      maxDelayMs: 2000,
      jitter: true,
    },
    perProviderTimeoutMs = 15_000,
    shouldRetry = defaultShouldRetry,
    shouldFallback = defaultShouldFallback,
    onAttemptStart,
    onAttemptFailure,
    onProviderFallback,
    onSuccess,
  } = options;

  if (!providers.length) {
    throw new Error("At least one provider must be configured");
  }

  const attempts: FallbackAttempt[] = [];

  for (const provider of providers) {
    const startedAt = Date.now();

    try {
      const result = await executeWithRetry(
        provider,
        params,
        retryPolicy,
        perProviderTimeoutMs,
        shouldRetry,
        {
          onAttemptStart,
          onAttemptFailure,
        }
      );

      const latencyMs = Date.now() - startedAt;
      attempts.push({
        provider: provider.name,
        success: true,
        latencyMs,
      });

      onSuccess?.(provider.name, result);

      return {
        result,
        attempts,
      };
    } catch (error) {
      const normalized = normalizeUnknownError(provider.name, error);
      const latencyMs = Date.now() - startedAt;

      attempts.push({
        provider: provider.name,
        success: false,
        latencyMs,
        error: {
          message: normalized.message,
          code: normalized.code,
          retryable: normalized.retryable,
          status: normalized.status,
        },
      });

      if (!shouldFallback(normalized) || params.signal?.aborted) {
        throw new AllProvidersFailedError(attempts);
      }

      onProviderFallback?.(provider.name, normalized);
    }
  }

  throw new AllProvidersFailedError(attempts);
}
