  role: "system" | "user" | "assistant";
  content: string;
};

export type GenerateTextParams = {
  messages: AIModelMessage[];
  temperature?: number;
  maxTokens?: number;
  signal?: AbortSignal;
  metadata?: Record<string, unknown>;
};

export type ProviderUsage = {
  inputTokens?: number;
  outputTokens?: number;
  totalTokens?: number;
};

export type ProviderResult = {
  provider: string;
  model: string;
  text: string;
  usage?: ProviderUsage;
  latencyMs: number;
  finishReason?: string;
};

export type ProviderErrorCode =
  | "TIMEOUT"
  | "RATE_LIMIT"
  | "AUTH"
  | "INVALID_REQUEST"
  | "NETWORK"
  | "SERVER"
  | "ABORTED"
  | "UNKNOWN";

export class ProviderError extends Error {
  public readonly provider: string;
  public readonly code: ProviderErrorCode;
  public readonly retryable: boolean;
  public readonly status?: number;
  public readonly cause?: unknown;

  constructor(params: {
    provider: string;
    message: string;
    code: ProviderErrorCode;
    retryable: boolean;
    status?: number;
    cause?: unknown;
  }) {
    super(params.message);
    this.name = "ProviderError";
    this.provider = params.provider;
    this.code = params.code;
    this.retryable = params.retryable;
    this.status = params.status;
    this.cause = params.cause;
  }
}

export interface AIProvider {
  readonly name: string;
  generateText(params: GenerateTextParams): Promise<ProviderResult>;
}

export type RetryPolicy = {
  maxAttempts: number;
  baseDelayMs: number;
  maxDelayMs: number;
  jitter?: boolean;
};

export type FallbackAttempt = {
  provider: string;
  success: boolean;
  latencyMs: number;
  error?: {
    message: string;
    code?: ProviderErrorCode;
    retryable?: boolean;
    status?: number;
  };
};

export type GenerateWithFallbackResult = {
  result: ProviderResult;
  attempts: FallbackAttempt[];
};

export type GenerateWithFallbackOptions = {
  providers: AIProvider[];
  retryPolicy?: RetryPolicy;
  perProviderTimeoutMs?: number;
  shouldRetry?: (error: unknown) => boolean;
  shouldFallback?: (error: unknown) => boolean;
  onAttemptStart?: (providerName: string, attemptNumber: number) => void;
  onAttemptFailure?: (providerName: string, error: unknown, attemptNumber: number) => void;
  onProviderFallback?: (fromProvider: string, error: unknown) => void;
  onSuccess?: (providerName: string, result: ProviderResult) => void;
};

export class AllProvidersFailedError extends Error {
  public readonly attempts: FallbackAttempt[];

  constructor(attempts: FallbackAttempt[]) {
    super("All AI providers failed");
    this.name = "AllProvidersFailedError";
    this.attempts = attempts;
  }
}

function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

function computeBackoffDelay(
  attempt: number,
  baseDelayMs: number,
  maxDelayMs: number,
  jitter = true
): number {
  const exp = Math.min(maxDelayMs, baseDelayMs * 2 ** (attempt - 1));
  if (!jitter) return exp;
  const randomized = exp * (0.5 + Math.random() * 0.5);
  return Math.floor(randomized);
}

function isAbortError(error: unknown): boolean {
  return error instanceof Error && error.name === "AbortError";
}

function normalizeUnknownError(provider: string, error: unknown): ProviderError {
  if (error instanceof ProviderError) {
    return error;
  }

  if (isAbortError(error)) {
    return new ProviderError({
      provider,
      message: "Request aborted",
      code: "ABORTED",
      retryable: false,
      cause: error,
    });
  }

  return new ProviderError({
    provider,
    message: error instanceof Error ? error.message : "Unknown provider error",
    code: "UNKNOWN",
    retryable: false,
    cause: error,
  });
}

function defaultShouldRetry(error: unknown): boolean {
  const normalized =
    error instanceof ProviderError
      ? error
