# 1. 휴리스틱 평가 함수

이 단계는 빠르고 deterministic 하게 동작합니다.

## 평가 기준 예시

- **relevance**: 사용자 프롬프트 키워드와 응답의 관련성
- **completeness**: 너무 짧거나 미완성인지
- **clarity**: 문장 가독성, 지나친 반복 여부
- **structure**: 목록, 섹션, 코드블록 등
- **safety**: 노골적 위험/정책 위반 감점

아래는 production에서 바로 쓸 수 있는 기본 구현입니다.

```ts
function normalizeText(text: string): string {
  return text
    .replace(/\r\n/g, '\n')
    .replace(/\s+/g, ' ')
    .trim()
    .toLowerCase();
}

function tokenize(text: string): string[] {
  return normalizeText(text)
    .split(/[^a-zA-Z0-9가-힣_]+/)
    .filter(Boolean);
}

function unique<T>(arr: T[]): T[] {
  return [...new Set(arr)];
}

function keywordOverlapScore(prompt: string, response: string): number {
  const promptTokens = unique(tokenize(prompt)).filter(t => t.length >= 2);
  const responseTokens = new Set(tokenize(response));

  if (promptTokens.length === 0) return 5;

  const overlap = promptTokens.filter(t => responseTokens.has(t)).length;
  const ratio = overlap / promptTokens.length;

  return Math.max(0, Math.min(10, Math.round(ratio * 10)));
}

function completenessScore(response: string): number {
  const len = response.trim().length;
  if (len === 0) return 0;
  if (len < 40) return 2;
  if (len < 120) return 4;
  if (len < 300) return 6;
  if (len < 800) return 8;
  return 9;
}

function clarityScore(response: string): number {
  const text = response.trim();
  if (!text) return 0;

  let score = 6;

  if (/[.!?]\s/.test(text)) score += 1;
  if (text.includes('\n')) score += 1;
  if (text.length > 80 && text.length < 4000) score += 1;

  const repeatedPhrasePenalty = /(.)\1{6,}/.test(text) ? 2 : 0;
  score -= repeatedPhrasePenalty;

  return Math.max(0, Math.min(10, score));
}

function structureScore(response: string): number {
  let score = 3;
  if (response.includes('\n')) score += 2;
  if (/^[-*]\s/m.test(response) || /^\d+\.\s/m.test(response)) score += 2;
  if (/```[\s\S]*?```/.test(response)) score += 2;
  if (/^#{1,6}\s/m.test(response)) score += 1;
  return Math.max(0, Math.min(10, score));
}

function safetyScore(response: string): number {
  const lower = normalizeText(response);

  const dangerousPatterns = [
    /how to make a bomb/,
    /bypass security/,
    /steal password/,
    /malware/,
    /ransomware/,
  ];

  const hit = dangerousPatterns.some(p => p.test(lower));
  return hit ? 1 : 10;
}

function detectObviousFailure(response: string): string | null {
  const trimmed = response.trim().toLowerCase();
  if (!trimmed) return 'empty response';
  if (trimmed.includes('error') && trimmed.length < 120) return 'possible error message';
  if (trimmed.includes('i cannot provide') && trimmed.length < 80) return 'possible refusal without useful alternative';
  return null;
}

export function scoreHeuristically(prompt: string, response: string): HeuristicScoreDetail {
  const reasons: string[] = [];

  const failure = detectObviousFailure(response);
  if (failure) {
    reasons.push(`Detected issue: ${failure}`);
  }

  const relevance = keywordOverlapScore(prompt, response);
  const completeness = completenessScore(response);
  const clarity = clarityScore(response);
  const structure = structureScore(response);
  const safety = safetyScore(response);

  if (relevance >= 8) reasons.push('High prompt-response keyword overlap');
  if (completeness <= 3) reasons.push('Response may be too short or incomplete');
  if (structure >= 7) reasons.push('Well-structured formatting');
  if (safety <= 3) reasons.push('Potential safety concern detected');

  let total = relevance + completeness + clarity + structure + safety;

  if (failure) total -= 5;

  total = Math.max(0, Math.min(50, total));

  return {
    relevance,
    completeness,
    clarity,
    structure,
    safety,
    total,
    reasons,
  };
}
```

