  quality: number;
  schemaValidity: number;
  safety: number;
  providerPreference: number;
}

export interface ScoreBreakdown {
  provider: ProviderName;
  totalScore: number;
  components: {
    success: number;
    latency: number;
    cost: number;
    quality: number;
    schemaValidity: number;
    safety: number;
    providerPreference: number;
  };
  reasons: string[];
  response: ProviderResponse;
}

export interface WinnerResult {
  winner: ScoreBreakdown | null;
  ranked: ScoreBreakdown[];
}

const DEFAULT_WEIGHTS: ScoreWeights = {
  success: 0.30,
  latency: 0.15,
  cost: 0.10,
  quality: 0.25,
  schemaValidity: 0.10,
  safety: 0.05,
  providerPreference: 0.05,
};

function clamp(value: number, min = 0, max = 1): number {
  return Math.max(min, Math.min(max, value));
}

/**
 * latency가 낮을수록 높은 점수
 * maxLatency를 넘으면 0에 가까워짐
 */
function scoreLatency(latencyMs: number, maxLatencyMs = 5000): number {
  if (latencyMs < 0) return 0;
  const normalized = 1 - latencyMs / maxLatencyMs;
  return clamp(normalized);
}

/**
 * cost가 낮을수록 높은 점수
 * maxCost를 넘으면 0에 가까워짐
 */
function scoreCost(costUsd: number, maxCostUsd = 0.05): number {
  if (costUsd < 0) return 0;
  const normalized = 1 - costUsd / maxCostUsd;
  return clamp(normalized);
}

function scoreSuccess(success: boolean): number {
  return success ? 1 : 0;
}

function scoreSchemaValidity<T>(
  content: T | null,
  expectedSchema?: (content: T) => boolean
): number {
  if (!content || !expectedSchema) return 0;
  try {
    return expectedSchema(content) ? 1 : 0;
  } catch {
    return 0;
  }
}

function scoreQuality<T>(
  content: T | null,
  evaluator?: (content: T) => number
): number {
  if (!content || !evaluator) return 0.5; // evaluator 없으면 중립값
  try {
    return clamp(evaluator(content));
  } catch {
    return 0;
  }
}

function scoreSafety<T>(
  content: T | null,
  evaluator?: (content: T) => number
): number {
  if (!content || !evaluator) return 0.5; // evaluator 없으면 중립값
  try {
    return clamp(evaluator(content));
  } catch {
    return 0;
  }
}

function scoreProviderPreference(
  provider: ProviderName,
  preferredProviders?: ProviderName[]
): number {
  if (!preferredProviders || preferredProviders.length === 0) return 0.5;
  return preferredProviders.includes(provider) ? 1 : 0;
}

export function evaluateResponse<T>(
  response: ProviderResponse<T>,
  context: EvaluationContext<T>,
  weights: ScoreWeights = DEFAULT_WEIGHTS
): ScoreBreakdown {
  const reasons: string[] = [];

  const success = scoreSuccess(response.success);
  const latency = scoreLatency(
    response.latencyMs,
    context.maxAcceptableLatencyMs ?? 5000
  );
  const cost = scoreCost(
    response.costUsd,
    context.maxAcceptableCostUsd ?? 0.05
  );
  const quality = scoreQuality(response.content, context.qualityEvaluator);
  const schemaValidity = scoreSchemaValidity(
    response.content,
    context.expectedSchema
  );
  const safety = scoreSafety(response.content, context.safetyEvaluator);
  const providerPreference = scoreProviderPreference(
    response.provider,
    context.preferredProviders
  );

  if (!response.success) {
    reasons.push(`Provider ${response.provider} failed`);
  }
  if (response.error) {
    reasons.push(`Error: ${response.error}`);
  }
  if (latency < 0.3) {
    reasons.push(`High latency: ${response.latencyMs}ms`);
  }
  if (cost < 0.3) {
    reasons.push(`High cost: $${response.costUsd.toFixed(4)}`);
  }
  if (schemaValidity === 0) {
    reasons.push(`Schema validation failed or unavailable`);
  }
  if (quality < 0.4) {
    reasons.push(`Low quality score`);
  }
  if (safety < 0.4) {
    reasons.push(`Low safety score`);
  }

  const totalScore =
    success * weights.success +
    latency * weights.latency +
    cost * weights.cost +
    quality * weights.quality +
    schemaValidity * weights.schemaValidity +
    safety * weights.safety +
    providerPreference * weights.providerPreference;

  return {
    provider: response.provider,
    totalScore,
    components: {
      success,
      latency,
      cost,
      quality,
      schemaValidity,
      safety,
      providerPreference,
    },
    reasons,
    response,
  };
}

export function rankProviders<T>(
  responses: ProviderResponse<T>[],
  context: EvaluationContext<T>,
  weights: ScoreWeights = DEFAULT_WEIGHTS
): ScoreBreakdown[] {
  return responses
    .map((response) => evaluateResponse(response, context, weights))
    .sort((a, b) => {
      // 1차: totalScore 내림차순
      if (b.totalScore !== a.totalScore) {
        return b.totalScore - a.totalScore;
      }

      // 2차 tie-breaker: success 우선
      if (b.components.success !== a.components.success) {
        return b.components.success - a.components.success;
      }

      // 3차 tie-breaker: quality 우선
      if (b.components.quality !== a.components.quality) {
        return b.components.quality - a.components.quality;
      }

      // 4차 tie-breaker: latency 낮은 쪽 우선
      return a.response.latencyMs - b.response.latencyMs;
    });
}

export function pickWinner<T>(
  responses: ProviderResponse<T>[],
  context: EvaluationContext<T>,
  weights: ScoreWeights = DEFAULT_WEIGHTS
): WinnerResult {
  const ranked = rankProviders(responses, context, weights);

  if (ranked.length === 0) {
    return { winner: null, ranked: [] };
  }

  const winner = ranked[0];

  // optional: 최소 기준 미달 시 winner를 null 처리
  if (
    winner.components.success === 0 ||
    winner.totalScore < 0.4
  ) {
    return { winner: null, ranked };
  }

  return { winner, ranked };
}
