// example.ts

import {
  ProviderResponse,
  EvaluationContext,
  pickWinner,
} from "./scoreboard";

type LlmOutput = {
  answer: string;
  citations?: string[];
};

const responses: ProviderResponse<LlmOutput>[] = [
  {
    provider: "openai",
    success: true,
    latencyMs: 1200,
    costUsd: 0.018,
    content: {
      answer: "TypeScript scoreboard implementation example",
      citations: ["doc1", "doc2"],
    },
  },
  {
    provider: "anthropic",
    success: true,
    latencyMs: 900,
    costUsd: 0.022,
    content: {
      answer: "A robust scoreboard-based evaluator in TypeScript",
      citations: ["docA"],
    },
  },
  {
    provider: "google",
    success: false,
    latencyMs: 3000,
    costUsd: 0.010,
    content: null,
    error: "Timeout",
  },
];

const context: EvaluationContext<LlmOutput> = {
  requestId: "req_123",
  expectedSchema: (content) => {
    return (
      typeof content.answer === "string" &&
      content.answer.length > 0 &&
      Array.isArray(content.citations)
    );
  },
  qualityEvaluator: (content) => {
    // 예시: answer 길이와 citations 존재 여부로 단순 평가
    let score = 0.4;
    if (content.answer.length > 20) score += 0.3;
    if (content.citations && content.citations.length > 0) score += 0.3;
    return Math.min(score, 1);
  },
  safetyEvaluator: (content) => {
    // 예시: 금칙어 없으면 높은 점수
    const bannedWords = ["hack", "exploit"];
    const hasBanned = bannedWords.some((word) =>
      content.answer.toLowerCase().includes(word)
    );
    return hasBanned ? 0.1 : 1;
  },
  preferredProviders: ["openai", "anthropic"],
  maxAcceptableLatencyMs: 2500,
  maxAcceptableCostUsd: 0.03,
};

const result = pickWinner(responses, context);

console.log("Winner:", result.winner);
console.log("Ranked:", result.ranked);
