import { PlanningError } from "../domain/errors";
import { ExecutionPlan, OrchestrationInput, PlanStep } from "../domain/types";
import { Logger } from "../utils/logger";
import { randomUUID } from "crypto";

export interface Planner {
  createPlan(input: OrchestrationInput): Promise<ExecutionPlan>;
}

export class SimplePlanner implements Planner {
  private readonly logger = new Logger("SimplePlanner");

  async createPlan(input: OrchestrationInput): Promise<ExecutionPlan> {
    this.logger.info("Creating plan", { requestId: input.requestId, goal: input.goal });

    if (!input.rawText || input.rawText.trim().length === 0) {
      throw new PlanningError("rawText must not be empty");
    }

    const steps: PlanStep[] = [];

    if (input.goal === "normalize") {
      steps.push({
        id: randomUUID(),
        type: "uppercase"
      });
    } else if (input.goal === "transform") {
      steps.push({
        id: randomUUID(),
        type: "reverse"
      });
      steps.push({
        id: randomUUID(),
        type: "append",
        params: { suffix: "_DONE" }
      });
    } else {
      throw new PlanningError(`Unsupported goal: ${String(input.goal)}`);
    }

    const plan: ExecutionPlan = {
      planId: randomUUID(),
      steps,
      createdAt: new Date().toISOString()
    };

    this.logger.info("Plan created", { planId: plan.planId, stepCount: plan.steps.length });

    return plan;
  }
}
