# 8) Executor 구현

계획의 각 step을 순서대로 실행합니다.

## `src/services/executor.ts`

```ts
import { ExecutionError } from "../domain/errors";
import {
  ExecutionPlan,
  ExecutionResult,
  PlanStep,
  StepExecutionResult
} from "../domain/types";
import { Logger } from "../utils/logger";

export interface Executor {
  execute(plan: ExecutionPlan, initialInput: string): Promise<ExecutionResult>;
}

export class SimpleExecutor implements Executor {
  private readonly logger = new Logger("SimpleExecutor");

  async execute(plan: ExecutionPlan, initialInput: string): Promise<ExecutionResult> {
    this.logger.info("Execution started", { planId: plan.planId });

    const startedAt = new Date().toISOString();
    const stepResults: StepExecutionResult[] = [];

    let currentOutput = initialInput;
    let overallSuccess = true;

    for (const step of plan.steps) {
      const result = await this.executeStep(step, currentOutput);
      stepResults.push(result);

      if (!result.success) {
        overallSuccess = false;
        break;
      }

      currentOutput = result.output;
    }

    const executionResult: ExecutionResult = {
      planId: plan.planId,
      finalOutput: currentOutput,
      stepResults,
      success: overallSuccess,
      startedAt,
      finishedAt: new Date().toISOString()
    };

    this.logger.info("Execution finished", {
      planId: plan.planId,
      success: executionResult.success,
      finalOutput: executionResult.finalOutput
    });

    return executionResult;
  }

  private async executeStep(step: PlanStep, input: string): Promise<StepExecutionResult> {
    const startedAt = new Date().toISOString();

    try {
      this.logger.info("Executing step", { stepId: step.id, type: step.type, input });

      let output: string;

      switch (step.type) {
        case "uppercase":
          output = input.toUpperCase();
          break;
        case "reverse":
          output = input.split("").reverse().join("");
          break;
        case "append":
          output = input + (step.params?.suffix ?? "");
          break;
        default:
          throw new ExecutionError(`Unsupported step type: ${String(step.type)}`);
      }

      return {
        stepId: step.id,
        type: step.type,
        success: true,
        output,
        startedAt,
        finishedAt: new Date().toISOString()
      };
    } catch (error) {
      const message = error instanceof Error ? error.message : "Unknown execution error";

      this.logger.error("Step execution failed", {
        stepId: step.id,
        type: step.type,
        error: message
      });

      return {
        stepId: step.id,
        type: step.type,
        success: false,
        output: input,
        error: message,
        startedAt,
        finishedAt: new Date().toISOString()
      };
    }
  }
}
```

