### `src/router/ProviderRouter.ts`

```ts
import { Provider } from '../providers/Provider';
import { NotificationRequest } from '../types/notification';

export class ProviderRouter {
  constructor(private readonly providers: Provider[]) {
    if (providers.length === 0) {
      throw new Error('At least one provider must be registered');
    }
  }

  resolve(request: NotificationRequest): Provider {
    // 1. providerHint가 있으면 우선 시도
    if (request.providerHint) {
      const hinted = this.providers.find(
        (provider) =>
          provider.name === request.providerHint && provider.supports(request)
      );

      if (hinted) {
        return hinted;
      }
    }

    // 2. supports 가능한 첫 provider 선택
    const matched = this.providers.find((provider) => provider.supports(request));

    if (!matched) {
      throw new Error(
        `No provider found for channel=${request.channel}, to=${request.to}`
      );
    }

    return matched;
  }
}
