## 11. fallback까지 포함한 간단한 실무형 예시

아래처럼 router가 여러 후보를 반환하고, 서비스가 순차 fallback을 시도할 수도 있습니다.

### `src/router/ProviderRouter.ts`

```ts
import { Provider } from '../providers/Provider';
import { NotificationRequest } from '../types/notification';

export class ProviderRouter {
  private readonly providers: Provider[];

  constructor(providers: Provider[]) {
    this.providers = [...providers].sort((a, b) => b.priority - a.priority);
  }

  resolveCandidates(request: NotificationRequest): Provider[] {
    const candidates = this.providers.filter((provider) => provider.supports(request));

    if (request.providerHint) {
      const hinted = candidates.find((provider) => provider.name === request.providerHint);
      if (hinted) {
        return [hinted, ...candidates.filter((p) => p.name !== hinted.name)];
      }
    }

    return candidates;
  }
}
```

### `src/services/NotificationService.ts`

```ts
import { ProviderRouter } from '../router/ProviderRouter';
import { NotificationRequest, NotificationResult } from '../types/notification';

export class NotificationService {
  constructor(private readonly providerRouter: ProviderRouter) {}

  async send(request: NotificationRequest): Promise<NotificationResult> {
    const candidates = this.providerRouter.resolveCandidates(request);

    if (candidates.length === 0) {
      throw new Error('No available providers');
    }

    let lastError: unknown;

    for (const provider of candidates) {
      try {
        return await provider.send(request);
      } catch (error) {
        lastError = error;
        console.error(`Provider ${provider.name} failed:`, error);
      }
    }

    throw new Error(`All providers failed. Last error: ${String(lastError)}`);
  }
}
```

이 패턴은 특히:

- 결제 provider 라우팅
- LLM provider 라우팅
- 메시징/email/sms provider 라우팅
- 스토리지 provider 라우팅

같은 곳에서 자주 사용됩니다.

