  public readonly retryable: boolean;
  public override readonly cause?: unknown;

  constructor(params: {
    provider: AIProviderName;
    code: AIErrorCode;
    message: string;
    status?: number;
    retryable?: boolean;
    cause?: unknown;
  }) {
    super(params.message);
    this.name = "AIProviderError";
    this.provider = params.provider;
    this.code = params.code;
    this.status = params.status;
    this.retryable = params.retryable ?? false;
    this.cause = params.cause;
  }
}

export interface AIProvider {
  name: AIProviderName;
  generate(request: AIRequest, signal?: AbortSignal): Promise<AIResponse>;
}

export interface RetryPolicy {
  maxAttempts: number; // 2 => 최초 1회 + 재시도 1회
  baseDelayMs: number;
  maxDelayMs: number;
}

export interface OrchestratorOptions {
  providers: AIProvider[];
  retryPolicy?: RetryPolicy;
  logger?: Pick<Console, "info" | "warn" | "error">;
}

export interface OrchestratorAttempt {
  provider: AIProviderName;
  success: boolean;
  latencyMs: number;
  error?: {
    code: AIErrorCode;
    message: string;
    status?: number;
    retryable: boolean;
  };
}

export interface OrchestratorResult {
  response: AIResponse;
  attempts: OrchestratorAttempt[];
}

function sleep(ms: number, signal?: AbortSignal): Promise<void> {
  return new Promise((resolve, reject) => {
    const timer = setTimeout(() => {
      cleanup();
      resolve();
    }, ms);

    const onAbort = () => {
      clearTimeout(timer);
      cleanup();
      reject(
        new AIProviderError({
          provider: "openai",
          code: "ABORTED",
          message: "Operation aborted",
          retryable: false,
        })
      );
    };

    const cleanup = () => {
      if (signal) {
        signal.removeEventListener("abort", onAbort);
      }
    };

    if (signal) {
      if (signal.aborted) {
        onAbort();
        return;
      }
      signal.addEventListener("abort", onAbort, { once: true });
    }
  });
}

function withTimeout<T>(
  promiseFactory: (signal: AbortSignal) => Promise<T>,
  timeoutMs: number,
  provider: AIProviderName,
  parentSignal?: AbortSignal
): Promise<T> {
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), timeoutMs);

  const abortParent = () => controller.abort();

  if (parentSignal) {
    if (parentSignal.aborted) {
      controller.abort();
    } else {
      parentSignal.addEventListener("abort", abortParent, { once: true });
    }
  }

  return promiseFactory(controller.signal)
    .catch((err) => {
      if (parentSignal?.aborted) {
        throw new AIProviderError({
          provider,
          code: "ABORTED",
          message: `Provider ${provider} aborted by caller`,
          retryable: false,
          cause: err,
        });
      }

      if (controller.signal.aborted) {
        throw new AIProviderError({
          provider,
          code: "TIMEOUT",
          message: `Provider ${provider} timed out after ${timeoutMs}ms`,
          retryable: true,
          cause: err,
        });
      }

      throw err;
    })
    .finally(() => {
      clearTimeout(timeout);
      if (parentSignal) {
        parentSignal.removeEventListener("abort", abortParent);
      }
    });
}

function backoffDelay(attempt: number, policy: RetryPolicy): number {
  const exp = policy.baseDelayMs * Math.pow(2, attempt - 1);
  const jitter = Math.floor(Math.random() * 100);
  return Math.min(exp + jitter, policy.maxDelayMs);
}

function normalizeUnknownError(
  provider: AIProviderName,
  err: unknown
): AIProviderError {
  if (err instanceof AIProviderError) return err;

  if (err instanceof Error) {
    return new AIProviderError({
      provider,
      code: "UNKNOWN",
      message: err.message,
      retryable: false,
      cause: err,
    });
  }

  return new AIProviderError({
    provider,
    code: "UNKNOWN",
    message: "Unknown provider error",
    retryable: false,
    cause: err,
  });
}

function mapHttpError(
  provider: AIProviderName,
  status: number,
  data: any
): AIProviderError {
  const message =
    data?.error?.message ||
    data?.message ||
    `Provider ${provider} returned HTTP ${status}`;

  if (status === 400) {
    return new AIProviderError({
      provider,
      code: "INVALID_REQUEST",
      message,
      status,
      retryable: false,
      cause: data,
    });
  }

  if (status === 401 || status === 403) {
    return new AIProviderError({
      provider,
      code: "AUTH",
      message,
      status,
      retryable: false,
      cause: data,
    });
  }

  if (status === 429) {
    return new AIProviderError({
      provider,
      code: "RATE_LIMIT",
      message,
      status,
      retryable: true,
      cause: data,
    });
  }

  if (status >= 500) {
    return new AIProviderError({
      provider,
      code: "PROVIDER",
      message,
      status,
      retryable: true,
      cause: data,
    });
  }

  return new AIProviderError({
    provider,
    code: "PROVIDER",
    message,
    status,
    retryable: false,
    cause: data,
  });
}

export class AIOrchestrator {
  private readonly providers: AIProvider[];
  private readonly retryPolicy: RetryPolicy;
  private readonly logger: Pick<Console, "info" | "warn" | "error">;

  constructor(options: OrchestratorOptions) {
    if (!options.providers.length) {
      throw new Error("At least one provider must be configured");
    }

    this.providers = options.providers;
    this.retryPolicy = options.retryPolicy ?? {
      maxAttempts: 2,
      baseDelayMs: 300,
      maxDelayMs: 2000,
    };
    this.logger = options.logger ?? console;
  }

  async generate(
    request: AIRequest,
    signal?: AbortSignal
  ): Promise<OrchestratorResult> {
    const attempts: OrchestratorAttempt[] = [];
    const timeoutMs = request.timeoutMs ?? 15_000;

    for (const provider of this.providers) {
      for (let attempt = 1; attempt <= this.retryPolicy.maxAttempts; attempt++) {
        const startedAt = Date.now();

        try {
          this.logger.info?.(
            `[AIOrchestrator] provider=${provider.name} attempt=${attempt} start`
          );

          const response = await withTimeout(
            (providerSignal) => provider.generate(request, providerSignal),
            timeoutMs,
            provider.name,
            signal
          );

          const latencyMs = Date.now() - startedAt;

          attempts.push({
            provider: provider.name,
            success: true,
            latencyMs,
          });

          this.logger.info?.(
            `[AIOrchestrator] provider=${provider.name} attempt=${attempt} success latencyMs=${latencyMs}`
          );

          return { response, attempts };
        } catch (error) {
          const normalized = normalizeUnknownError(provider.name, error);
          const latencyMs = Date.now() - startedAt;

          attempts.push({
            provider: provider.name,
            success: false,
            latencyMs,
            error: {
              code: normalized.code,
              message: normalized.message,
              status: normalized.status,
              retryable: normalized.retryable,
            },
          });

          this.logger.warn?.(
            `[AIOrchestrator] provider=${provider.name} attempt=${attempt} failed code=${normalized.code} retryable=${normalized.retryable} latencyMs=${latencyMs} message=${normalized.message}`
          );

          if (normalized.code === "ABORTED") {
            throw normalized;
          }

          const canRetry =
            normalized.retryable && attempt < this.retryPolicy.maxAttempts;

          if (canRetry) {
            const delay = backoffDelay(attempt, this.retryPolicy);
            this.logger.info?.(
              `[AIOrchestrator] provider=${provider.name} retrying in ${delay}ms`
            );
            await sleep(delay, signal);
            continue;
          }

          // 현재 provider는 포기하고 다음 provider로 fallback
          break;
        }
      }
    }

    throw new Error(
      `All providers failed. Attempts=${JSON.stringify(attempts, null, 2)}`
    );
  }
}
