```ts
function sleep(ms: number, signal?: AbortSignal): Promise<void> {
  return new Promise((resolve, reject) => {
    const timer = setTimeout(resolve, ms);

    if (signal) {
      const onAbort = () => {
        clearTimeout(timer);
        reject(
          new AIProviderError({
            provider: "openai", // 실제 provider와 무관한 generic abort 처리용. 아래에서 재매핑 가능
            code: "ABORTED",
            message: "Operation aborted",
            retryable: false,
          })
        );
      };

      if (signal.aborted) {
        onAbort();
        return;
      }

      signal.addEventListener("abort", onAbort, { once: true });
    }
  });
}

function withTimeout<T>(
  promiseFactory: (signal: AbortSignal) => Promise<T>,
  timeoutMs: number,
  provider: AIProviderName,
  parentSignal?: AbortSignal
): Promise<T> {
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), timeoutMs);

  const abortParent = () => controller.abort();
  if (parentSignal) {
    if (parentSignal.aborted) {
      controller.abort();
    } else {
      parentSignal.addEventListener("abort", abortParent, { once: true });
    }
  }

  return promiseFactory(controller.signal)
    .catch((err) => {
      if (controller.signal.aborted && !(parentSignal?.aborted)) {
        throw new AIProviderError({
          provider,
          code: "TIMEOUT",
          message: `Provider ${provider} timed out after ${timeoutMs}ms`,
          retryable: true,
          cause: err,
        });
      }

      if (parentSignal?.aborted) {
        throw new AIProviderError({
          provider,
          code: "ABORTED",
          message: `Provider ${provider} aborted by caller`,
          retryable: false,
          cause: err,
        });
      }

      throw err;
    })
    .finally(() => {
      clearTimeout(timeout);
      if (parentSignal) {
        parentSignal.removeEventListener("abort", abortParent);
      }
    });
}

function backoffDelay(attempt: number, policy: RetryPolicy): number {
  const exp = policy.baseDelayMs * Math.pow(2, attempt - 1);
  const jitter = Math.floor(Math.random() * 100);
  return Math.min(exp + jitter, policy.maxDelayMs);
}

function normalizeUnknownError(provider: AIProviderName, err: unknown): AIProviderError {
  if (err instanceof AIProviderError) return err;

  if (err instanceof Error) {
    return new AIProviderError({
      provider,
      code: "UNKNOWN",
      message: err.message,
      retryable: false,
      cause: err,
    });
  }

  return new AIProviderError({
    provider,
    code: "UNKNOWN",
    message: "Unknown provider error",
    retryable: false,
    cause: err,
  });
}
