# 4) 유틸 함수

```ts
function isBlank(text: string): boolean {
  return !text || text.trim().length === 0;
}

function wordCount(text: string): number {
  return text.trim().split(/\s+/).filter(Boolean).length;
}

function clamp(value: number, min: number, max: number): number {
  return Math.max(min, Math.min(max, value));
}

function defaultScore(): ScoreBreakdown {
  return {
    instructionFollowing: 1,
    correctness: 1,
    completeness: 1,
    clarity: 1,
    safety: 1,
  };
}

function totalScore(score: ScoreBreakdown): number {
  return (
    score.instructionFollowing +
    score.correctness +
    score.completeness +
    score.clarity +
    score.safety
  );
}

function looksLikeJson(text: string): boolean {
  const trimmed = text.trim();
  if (!(trimmed.startsWith('{') || trimmed.startsWith('['))) return false;
  try {
    JSON.parse(trimmed);
    return true;
  } catch {
    return false;
  }
}

function maybeShuffle<T>(items: [T, T]): { shuffled: [T, T]; swapped: boolean } {
  const swapped = Math.random() < 0.5;
  return swapped
    ? { shuffled: [items[1], items[0]], swapped: true }
    : { shuffled: items, swapped: false };
}
```

