function safeJsonParse(text: string): unknown {
  try {
    return JSON.parse(text);
  } catch {
    return null;
  }
}

function isValidScoreBreakdown(value: any): value is ScoreBreakdown {
  if (!value || typeof value !== 'object') return false;

  const keys: (keyof ScoreBreakdown)[] = [
    'instructionFollowing',
    'correctness',
    'completeness',
    'clarity',
    'safety',
  ];

  return keys.every((k) => Number.isInteger(value[k]) && value[k] >= 1 && value[k] <= 5);
}

function isValidRawJudgeResponse(value: any): value is RawJudgeResponse {
  if (!value || typeof value !== 'object') return false;
  if (!['A', 'B', 'tie'].includes(value.winner)) return false;
  if (typeof value.confidence !== 'number') return false;
  if (value.confidence < 0 || value.confidence > 1) return false;
  if (typeof value.reasoning !== 'string') return false;
  if (!value.scores || typeof value.scores !== 'object') return false;
  if (!isValidScoreBreakdown(value.scores.A)) return false;
  if (!isValidScoreBreakdown(value.scores.B)) return false;
  return true;
}
