## 4) rule-based fallback judge

LLM judge가 실패했을 때 최소한 동작하는 fallback입니다.

```ts
function fallbackJudge(input: JudgeInput): JudgeResult {
  const [c1, c2] = input.candidates;

  const score1 = defaultScore();
  const score2 = defaultScore();

  // 매우 단순한 휴리스틱
  if (!isBlank(c1.text)) {
    score1.clarity += 1;
    score1.completeness += wordCount(c1.text) > 30 ? 1 : 0;
  }

  if (!isBlank(c2.text)) {
    score2.clarity += 1;
    score2.completeness += wordCount(c2.text) > 30 ? 1 : 0;
  }

  // JSON task면 JSON-like 여부 가산
  if (input.taskType === 'json') {
    if (looksLikeJson(c1.text)) score1.instructionFollowing += 2;
    if (looksLikeJson(c2.text)) score2.instructionFollowing += 2;
  }

  const provider1 = c1.provider;
  const provider2 = c2.provider;

  const total1 = totalScore(score1);
  const total2 = totalScore(score2);

  let winner: JudgeWinner = 'tie';
  if (total1 > total2) winner = provider1;
  else if (total2 > total1) winner = provider2;

  return {
    winner,
    confidence: winner === 'tie' ? 0.2 : 0.4,
    scores: {
      [provider1]: score1,
      [provider2]: score2,
    } as Record<CandidateProvider, ScoreBreakdown>,
    reasoning: 'Fallback heuristic judge used due to LLM judge failure.',
    metadata: {
      judgeModel: 'fallback-heuristic',
      shuffled: false,
      latencyMs: 0,
      version: '1.0.0',
      rawWinner: winner === 'tie' ? 'tie' : provider1 === winner ? 'A' : 'B',
    },
  };
}

function looksLikeJson(text: string): boolean {
  const trimmed = text.trim();
  if (!(trimmed.startsWith('{') || trimmed.startsWith('['))) return false;
  try {
    JSON.parse(trimmed);
    return true;
  } catch {
    return false;
  }
}
```

