function isValidScoreBreakdown(value: any): value is ScoreBreakdown {
  if (!value || typeof value !== 'object') return false;

  const keys: (keyof ScoreBreakdown)[] = [
    'instructionFollowing',
    'correctness',
    'completeness',
    'clarity',
    'safety',
  ];

  return keys.every((k) => Number.isInteger(value[k]) && value[k] >= 1 && value[k] <= 5);
}

function isValidRawJudgeResponse(value: any): value is RawJudgeResponse {
