  if (typeof value.confidence !== 'number') return false;
  if (value.confidence < 0 || value.confidence > 1) return false;
  if (typeof value.reasoning !== 'string') return false;
  if (!value.scores || typeof value.scores !== 'object') return false;
  if (!isValidScoreBreakdown(value.scores.A)) return false;
  if (!isValidScoreBreakdown(value.scores.B)) return false;
  return true;
}
