## 3) 기본 평가 기준 구현

```ts
// default-criteria.ts

import {
  EvaluationContext,
  ProviderResponse,
  ScoreCriterion,
} from "./scoreboard";
import {
  clamp,
  getTextLength,
  looksLikeJson,
  looksLikeMarkdown,
} from "./scoreboard-utils";

export function availabilityCriterion<T>(): ScoreCriterion<T> {
  return {
    name: "availability",
    weight: 0.30,
    evaluate(response: ProviderResponse<T>) {
      if (!response.success) {
        return {
          score: 0,
          reason: response.error
            ? `request failed: ${response.error}`
            : "request failed",
        };
      }

      if (response.data == null) {
        return {
          score: 0.2,
          reason: "success=true but data is empty",
        };
      }

      return {
        score: 1,
        reason: "response available",
      };
    },
  };
}

export function latencyCriterion<T>(): ScoreCriterion<T> {
  return {
    name: "latency",
    weight: 0.20,
    evaluate(response: ProviderResponse<T>, context: EvaluationContext<T>) {
      const maxLatency = context.maxLatencyMs ?? 5000;

      if (!response.success) {
        return {
          score: 0,
          reason: "failed response gets no latency score",
        };
      }

      const ratio = 1 - response.latencyMs / maxLatency;
      const score = clamp(ratio, 0, 1);

      return {
        score,
        reason: `latency=${response.latencyMs}ms, max=${maxLatency}ms`,
      };
    },
  };
}

export function completenessCriterion<T>(): ScoreCriterion<T> {
  return {
    name: "completeness",
    weight: 0.30,
    evaluate(response: ProviderResponse<T>, context: EvaluationContext<T>) {
      if (!response.success || response.data == null) {
        return {
          score: 0,
          reason: "no usable content",
        };
      }

      const minLength = context.minLength ?? 100;
      const length = getTextLength(response.data);

      if (length === 0) {
        return {
          score: 0,
          reason: "empty content",
        };
      }

      const score = clamp(length / minLength, 0, 1);

      return {
        score,
        reason: `content length=${length}, target min=${minLength}`,
      };
    },
  };
}

export function formatComplianceCriterion<T>(): ScoreCriterion<T> {
  return {
    name: "formatCompliance",
    weight: 0.15,
    evaluate(response: ProviderResponse<T>, context: EvaluationContext<T>) {
      if (!response.success || response.data == null) {
        return {
          score: 0,
          reason: "no content to validate",
        };
      }

      const expected = context.expectedFormat ?? "unknown";

      if (expected === "unknown") {
        return {
          score: 1,
          reason: "no format requirement",
        };
      }

      let ok = false;
      if (expected === "json") ok = looksLikeJson(response.data);
      else if (expected === "markdown") ok = looksLikeMarkdown(response.data);
      else if (expected === "text") ok = true;

      return {
        score: ok ? 1 : 0,
        reason: ok
          ? `matches expected format: ${expected}`
          : `does not match expected format: ${expected}`,
      };
    },
  };
}

export function confidenceCriterion<T>(): ScoreCriterion<T> {
  return {
    name: "confidence",
    weight: 0.05,
    evaluate(response: ProviderResponse<T>) {
      const raw = response.metadata?.confidence;
      const confidence =
        typeof raw === "number" && Number.isFinite(raw)
          ? clamp(raw, 0, 1)
          : 0.5;

      return {
        score: response.success ? confidence : 0,
        reason: `confidence=${confidence}`,
      };
    },
  };
}
```

