```ts
// scoreboard-utils.ts

export function clamp(value: number, min = 0, max = 1): number {
  return Math.max(min, Math.min(max, value));
}

export function safeStringify(value: unknown): string {
  try {
    if (typeof value === "string") return value;
    return JSON.stringify(value);
  } catch {
    return String(value);
  }
}

export function getTextLength(data: unknown): number {
  if (data == null) return 0;
  if (typeof data === "string") return data.trim().length;
  return safeStringify(data).trim().length;
}

export function looksLikeJson(data: unknown): boolean {
  if (data == null) return false;
  if (typeof data === "object") return true;
  if (typeof data !== "string") return false;

  const trimmed = data.trim();
  if (!trimmed) return false;

  try {
    JSON.parse(trimmed);
    return true;
  } catch {
    return false;
  }
}

export function looksLikeMarkdown(data: unknown): boolean {
  if (typeof data !== "string") return false;
  const text = data.trim();
  if (!text) return false;

  return /(^#\s)|(\*\*.+\*\*)|(```[\s\S]*```)|(-\s)|(\d+\.\s)/m.test(text);
}
