## 4) Scoreboard 엔진

```ts
// scoreboard-engine.ts

import {
  EvaluationContext,
  ProviderResponse,
  ProviderScore,
  ScoreCriterion,
  ScoreCriterionResult,
  WinnerResult,
} from "./scoreboard";

export interface ScoreboardEngineOptions<T = unknown> {
  criteria: ScoreCriterion<T>[];
  tieBreaker?: (a: ProviderScore<T>, b: ProviderScore<T>) => number;
}

export class ScoreboardEngine<T = unknown> {
  private readonly criteria: ScoreCriterion<T>[];
  private readonly tieBreaker?: (a: ProviderScore<T>, b: ProviderScore<T>) => number;

  constructor(options: ScoreboardEngineOptions<T>) {
    if (!options.criteria.length) {
      throw new Error("ScoreboardEngine requires at least one criterion");
    }

    this.criteria = options.criteria;
    this.tieBreaker = options.tieBreaker;
  }

  evaluate(
    responses: ProviderResponse<T>[],
    context: EvaluationContext<T> = {}
  ): WinnerResult<T> {
    const scoreboard = responses.map((response) =>
      this.scoreResponse(response, context)
    );

    scoreboard.sort((a, b) => {
      if (b.normalizedScore !== a.normalizedScore) {
        return b.normalizedScore - a.normalizedScore;
      }

      if (this.tieBreaker) {
        return this.tieBreaker(a, b);
      }

      // 기본 tie-breaker
      // 1. success 우선
      // 2. latency 낮은 쪽 우선
      // 3. provider 이름 오름차순
      if (a.response.success !== b.response.success) {
        return a.response.success ? -1 : 1;
      }

      if (a.response.latencyMs !== b.response.latencyMs) {
        return a.response.latencyMs - b.response.latencyMs;
      }

      return a.provider.localeCompare(b.provider);
    });

    scoreboard.forEach((item, index) => {
      item.rank = index + 1;
    });

    return {
      winner: scoreboard[0] ?? null,
      scoreboard,
      evaluatedAt: Date.now(),
      tieBreakReason:
        "normalizedScore desc, then success, latency asc, provider asc",
    };
  }

  private scoreResponse(
    response: ProviderResponse<T>,
    context: EvaluationContext<T>
  ): ProviderScore<T> {
    const criteriaResults: ScoreCriterionResult[] = this.criteria.map(
      (criterion) => {
        const result = criterion.evaluate(response, context);
        const weightedScore = result.score * criterion.weight;

        return {
          criterion: criterion.name,
          score: result.score,
          weight: criterion.weight,
          weightedScore,
          reason: result.reason,
        };
      }
    );

    const totalWeight = this.criteria.reduce((sum, c) => sum + c.weight, 0);
    const totalScore = criteriaResults.reduce(
      (sum, c) => sum + c.weightedScore,
      0
    );
    const normalizedScore = totalWeight > 0 ? totalScore / totalWeight : 0;

    return {
      provider: response.provider,
      response,
      criteria: criteriaResults,
      totalScore,
      normalizedScore,
    };
  }
}
```

