export type WorkflowStatus =
  | "PLANNING"
  | "EXECUTING"
  | "JUDGING"
  | "COMPLETED"
  | "FAILED";

export interface WorkflowInput {
  requestId: string;
  userGoal: string;
  context?: Record<string, unknown>;
}

export interface PlanStep {
  id: string;
  description: string;
  actionType: "CALCULATE" | "LOOKUP" | "TRANSFORM";
  payload: Record<string, unknown>;
}

export interface Plan {
  summary: string;
  steps: PlanStep[];
}

export interface StepExecutionResult {
  stepId: string;
  success: boolean;
  output?: unknown;
  error?: string;
  startedAt: string;
  finishedAt: string;
}

export interface ExecutionResult {
  success: boolean;
  stepResults: StepExecutionResult[];
}

export interface Judgment {
  approved: boolean;
  score: number;
  reasons: string[];
  finalAnswer?: string;
}

export interface WorkflowState {
  requestId: string;
  status: WorkflowStatus;
  input: WorkflowInput;
  plan?: Plan;
  executionResult?: ExecutionResult;
  judgment?: Judgment;
  error?: string;
  createdAt: string;
  updatedAt: string;
}

export interface Planner {
  createPlan(input: WorkflowInput): Promise<Plan>;
}

export interface Executor {
  execute(plan: Plan): Promise<ExecutionResult>;
}

export interface Judge {
  evaluate(
    input: WorkflowInput,
    plan: Plan,
    execution: ExecutionResult
  ): Promise<Judgment>;
}
