import { Plan, Planner, WorkflowInput, PlanStep } from "./types";

export class SimplePlanner implements Planner {
  async createPlan(input: WorkflowInput): Promise<Plan> {
    const goal = input.userGoal.trim();
    const steps: PlanStep[] = [];

    if (goal.includes("합") || goal.toLowerCase().includes("sum")) {
      const numbers = this.extractNumbers(goal);

      if (numbers.length >= 2) {
        steps.push({
          id: "step-1",
          description: "입력 숫자를 정규화한다",
          actionType: "TRANSFORM",
          payload: { numbers }
        });

        steps.push({
          id: "step-2",
          description: "숫자의 합을 계산한다",
          actionType: "CALCULATE",
          payload: {
            operation: "sum",
            numbers
          }
