# 6) `src/judge.ts`

Judge는 실행 결과를 평가하고 최종 승인 여부를 결정합니다.

```ts
import { ExecutionResult, Judge, Judgment, Plan, WorkflowInput } from "./types";

export class SimpleJudge implements Judge {
  async evaluate(
    input: WorkflowInput,
    plan: Plan,
    execution: ExecutionResult
  ): Promise<Judgment> {
    const reasons: string[] = [];

    if (!execution.success) {
      reasons.push("실행 단계에서 실패한 step이 존재합니다.");
      return {
        approved: false,
        score: 0,
        reasons
      };
    }

    if (plan.steps.length === 0) {
      reasons.push("계획에 step이 없습니다.");
      return {
        approved: false,
        score: 10,
        reasons
      };
    }

    const lastStep = execution.stepResults[execution.stepResults.length - 1];
    if (!lastStep?.success) {
      reasons.push("마지막 step 결과가 유효하지 않습니다.");
      return {
        approved: false,
        score: 20,
        reasons
      };
    }

    let finalAnswer: string | undefined;
    let score = 80;

    const output = lastStep.output as Record<string, unknown> | undefined;

    if (output && typeof output.result === "number") {
      finalAnswer = `요청 "${input.userGoal}"의 결과는 ${output.result} 입니다.`;
      reasons.push("계산 결과가 정상적으로 생성되었습니다.");
      score = 95;
    } else if (output && typeof output.transformedText === "string") {
      finalAnswer = `변환 결과: ${output.transformedText}`;
      reasons.push("기본 변환 결과가 생성되었습니다.");
      score = 75;
    } else {
      reasons.push("출력 형식이 기대와 다릅니다.");
      score = 50;
    }

    return {
      approved: score >= 70,
      score,
      reasons,
      finalAnswer
    };
  }
}
