# 5) Planner 구현: `src/planner.ts`

여기서는 매우 단순한 규칙 기반 planner를 만듭니다.  
예시 목표가 `"1부터 5까지 합을 계산해줘"` 같은 경우를 처리할 수 있게 구성합니다.

```ts
import { Plan, Planner, WorkflowInput, PlanStep } from "./types";

export class SimplePlanner implements Planner {
  async createPlan(input: WorkflowInput): Promise<Plan> {
    const goal = input.userGoal.trim();

    const steps: PlanStep[] = [];

    // 매우 단순한 예시 planner
    if (goal.includes("합") || goal.toLowerCase().includes("sum")) {
      const numbers = this.extractNumbers(goal);

      if (numbers.length >= 2) {
        steps.push({
          id: "step-1",
          description: "입력 숫자 범위를 정규화한다",
          actionType: "TRANSFORM",
          payload: {
            numbers
          }
        });

        steps.push({
          id: "step-2",
          description: "숫자의 합을 계산한다",
          actionType: "CALCULATE",
          payload: {
            operation: "sum",
            numbers
          }
        });

        return {
          summary: "숫자 합계 계산 계획",
          steps
        };
      }
    }

    // fallback
    steps.push({
      id: "step-1",
      description: "입력 문장을 그대로 반환 가능한 형태로 변환한다",
      actionType: "TRANSFORM",
      payload: {
        text: goal
      }
    });

    return {
      summary: "기본 변환 계획",
      steps
    };
  }

  private extractNumbers(text: string): number[] {
    const matches = text.match(/-?\d+/g);
    if (!matches) return [];
    return matches.map(Number);
  }
}
```

