# 6) Executor 구현: `src/executor.ts`

각 step을 순차 실행합니다.  
실무에서는 여기서:

- 외부 API 호출
- DB 조회
- 파일 처리
- 툴 실행

등을 붙이면 됩니다.

```ts
import {
  ExecutionResult,
  Executor,
  Plan,
  PlanStep,
  StepExecutionResult
} from "./types";

export class SimpleExecutor implements Executor {
  async execute(plan: Plan): Promise<ExecutionResult> {
    const stepResults: StepExecutionResult[] = [];

    for (const step of plan.steps) {
      const result = await this.executeStep(step);
      stepResults.push(result);

      // 간단한 fail-fast 정책
      if (!result.success) {
        return {
          success: false,
          stepResults
        };
      }
    }

    return {
      success: true,
      stepResults
    };
  }

  private async executeStep(step: PlanStep): Promise<StepExecutionResult> {
    const startedAt = new Date().toISOString();

    try {
      let output: unknown;

      switch (step.actionType) {
        case "TRANSFORM":
          output = this.handleTransform(step.payload);
          break;
        case "CALCULATE":
          output = this.handleCalculate(step.payload);
          break;
        case "LOOKUP":
          output = this.handleLookup(step.payload);
          break;
        default:
          throw new Error(`Unsupported actionType: ${String(step.actionType)}`);
      }

      return {
        stepId: step.id,
        success: true,
        output,
        startedAt,
        finishedAt: new Date().toISOString()
      };
    } catch (error) {
      return {
        stepId: step.id,
        success: false,
        error: error instanceof Error ? error.message : "Unknown error",
        startedAt,
        finishedAt: new Date().toISOString()
      };
    }
  }

  private handleTransform(payload: Record<string, unknown>): unknown {
    if (Array.isArray(payload.numbers)) {
      const numbers = payload.numbers.map((v) => Number(v));
      return {
        normalizedNumbers: numbers
      };
    }

    if (typeof payload.text === "string") {
      return {
        transformedText: payload.text.trim()
      };
    }

    return payload;
  }

  private handleCalculate(payload: Record<string, unknown>): unknown {
    const operation = payload.operation;
    const numbersRaw = payload.numbers;

    if (operation !== "sum") {
      throw new Error(`Unsupported operation: ${String(operation)}`);
    }

    if (!Array.isArray(numbersRaw)) {
      throw new Error("numbers must be an array");
    }

    const numbers = numbersRaw.map((v) => Number(v));
    if (numbers.some((n) => Number.isNaN(n))) {
      throw new Error("numbers contains NaN");
    }

    const result = numbers.reduce((acc, cur) => acc + cur, 0);

    return {
      operation: "sum",
      numbers,
      result
    };
  }

  private handleLookup(payload: Record<string, unknown>): unknown {
    return {
      found: true,
      payload
    };
  }
}
